set -u
H="$(cd "$(dirname "$0")" && pwd)"
REPO="${1:-/f/StealAShop}"
# a265 (vague 79, 2e commit) : étape du maintien obligatoire dans le vrai code (garde « phase == nil or not
# HOLD_PHASES[phase] ») : tout le lancement passe par un faux luau.exe (HOME passager) qui applique a265-banc/etape.pl
# au fichier assemblé (appels de banc sans étape traduits en "Begin" / "End" par l'ancienne règle, voir etape.pl),
# puis appelle le luau.exe d'avant ; les corrige.sh des bancs s'enchaînent dessus. Arbre sans ce garde : rien.
A265_T=""
if grep -q 'if phase == nil or not HOLD_PHASES\[phase\] then' "${REPO%/src}/src/server/Services/StoreHeistService.luau" 2>/dev/null; then
	A265_T="$(mktemp -d)"
	mkdir -p "$A265_T/.rokit/bin"
	{
		echo '#!/usr/bin/env bash'
		echo 'for a in "$@"; do'
		echo '	case "$a" in *.luau)'
		echo '		f="$(cygpath -u "$a")"'
		echo "		if [ -f \"\$f\" ] && ! perl \"$H/a265-banc/etape.pl\" \"\$f\"; then echo \"ÉCHEC a265 : etape.pl pas appliqué à \$f : 0 vérification(s), 1 échec(s)\"; exit 1; fi ;;"
		echo '	esac'
		echo 'done'
		echo "exec \"$HOME/.rokit/bin/luau.exe\" \"\$@\""
	} > "$A265_T/.rokit/bin/luau.exe"
	chmod +x "$A265_T/.rokit/bin/luau.exe"
	export HOME="$A265_T"
fi
# a412 (vague GC7, 23/11) : arbre avec les textes d'a412 (message de la caisse « you got %s %s %s! ») : un 2e faux
# luau.exe, devant celui d'a265 s'il est là, applique a412-banc/textes.pl (anciens textes attendus par les scénarios
# remplacés mot pour mot par les nouveaux) à chaque fichier .luau lancé. Arbre sans a412 : rien de changé.
A412_T=""
if grep -q 'CrateItem = "Exclusive Crate: you got %s %s %s!"' "${REPO%/src}/src/server/Services/MonetizationService.luau" 2>/dev/null; then
	A412_T="$(mktemp -d)"
	mkdir -p "$A412_T/.rokit/bin"
	A412_NEXT="$HOME/.rokit/bin/luau.exe"
	{
		echo '#!/usr/bin/env bash'
		echo 'for a in "$@"; do'
		echo '	case "$a" in *.luau)'
		echo '		f="$(cygpath -u "$a")"'
		echo "		if [ -f \"\$f\" ] && ! perl \"$H/a412-banc/textes.pl\" \"\$f\"; then echo \"ÉCHEC a412 : textes.pl pas appliqué à \$f : 0 vérification(s), 1 échec(s)\"; exit 1; fi ;;"
		echo '	esac'
		echo 'done'
		echo "exec \"$A412_NEXT\" \"\$@\""
	} > "$A412_T/.rokit/bin/luau.exe"
	chmod +x "$A412_T/.rokit/bin/luau.exe"
	export HOME="$A412_T"
fi
SRC="$REPO/src"
