# fusion57 (vague 63) : ONLY="a206 a191 ..." ne lance que ces bancs (noms séparés par des espaces), comme les copies d a206, a208, a209, a210 et a211.
if [ -n "${ONLY:-}" ]; then
	kept=()
	for entry in "${BANCS[@]}"; do
		case " $ONLY " in *" ${entry%%:*} "*) kept+=("$entry") ;; esac
	done
	BANCS=("${kept[@]}")
fi
# Optimisation du 2026-11-11 (Ironix) : les bancs tournent JOBS à la fois (4 par défaut, JOBS=1 pour
# l'ancien comportement), chacun dans sa sortie à part ; le résumé s'affiche ensuite dans l'ordre de la
# liste, comme avant. Délai par banc porté de 240 à 600 s (plusieurs bancs se partagent le processeur).
JOBS="${JOBS:-$(bash "$H/r1-outils/jeton.sh" --n)}" # r1 : autant de bancs que de jetons
OUTDIR="$(mktemp -d)"; export R1_RUN="$OUTDIR" # r1 : dossier du lancement, hérité par les bancs
trap 'rm -rf "$OUTDIR" ${A265_T:+"$A265_T"} ${A412_T:+"$A412_T"}' EXIT
i=0
for entry in "${BANCS[@]}"; do
	i=$((i + 1))
	rest="${entry#*:}"; script="${rest%%:*}"; arg="${rest#*:}"
	( bash "$H/r1-outils/jeton.sh" timeout 600 bash "$script" "$arg" > "$OUTDIR/$i.out" 2>&1 ) & # r1 : jeton de processeur
	while [ "$(jobs -rp | wc -l)" -ge "$JOBS" ]; do wait -n || true; done
done
wait
total_fail=0
i=0
for entry in "${BANCS[@]}"; do
	i=$((i + 1))
	name="${entry%%:*}"
	out=$(cat "$OUTDIR/$i.out")
	# a291 : le verdict lit toutes les lignes de comptes (avant : la ligne coupée à 160 caractères, donc souvent le
	# premier compte d'un banc à plusieurs scénarios) et un scénario « arrêté avant la fin » compte comme un échec
	# même si les autres comptes sont à 0 ; l'affichage reste coupé à 160, avec la raison ajoutée quand elle est cachée.
	counts=$(printf '%s\n' "$out" | grep -E "vérification\(s\)|réussi\(s\)")
	summary=$(printf '%s\n' "$counts" | tr '\n' ' ' | cut -c1-160)
	why=""
	if [ -z "$counts" ]; then
		why="pas de résumé"
	elif printf '%s\n' "$counts" | grep -qE "[1-9][0-9]* échec"; then
		why="échec"
		if ! printf '%s\n' "$summary" | grep -qE "[1-9][0-9]* échec"; then summary="$summary [ÉCHEC plus loin dans les comptes]"; fi
	elif printf '%s\n' "$out" | grep -qE "arrêtée? avant la fin"; then
		why="arrêté"
		summary="$summary [ÉCHEC : scénario arrêté avant la fin]"
	fi
	printf '%-10s %s\n' "$name" "${summary:-PAS DE RÉSUMÉ}"
	if [ -n "$why" ]; then total_fail=$((total_fail + 1)); fi
	if [ "${DETAIL:-}" = "1" ]; then
		printf '%s\n' "$out" | grep -E "ÉCHEC|ERREUR|arrêtée? avant la fin" | head -12 | sed 's/^/    /'
	fi
done
echo "bancs en échec : $total_fail"
exit $((total_fail > 0))
